/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return (row?.value ?? 0) + 1;
}

input.new_string:
/**
 * Next per-project issue number.
 *
 * The counter remembers the highest number ever issued for the project.
 * Archived rows still hold their number, and a number whose issue has left
 * the project stays retired, so neither `max(number)` nor the high-water
 * mark is enough on its own.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const issued = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const remembered = db
    .select({ value: projects.issueNumberHighWater })
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();

  const next = Math.max(issued?.value ?? 0, remembered?.value ?? 0) + 1;
  db.update(projects)
    .set({ issueNumberHighWater: next })
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .run();
  return next;
}

/**
 * Records that `issueNumber` has been used in the project so a later
 * allocation cannot hand it out again. Never lowers the high-water mark.
 */
export async function retireIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<void> {
  const current = getDb()
    .select({ value: projects.issueNumberHighWater })
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();

  if (issueNumber <= (current?.value ?? 0)) return;

  getDb()
    .update(projects)
    .set({ issueNumberHighWater: issueNumber })
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .run();
}

/**
 * Points an issue at another project and gives it that project's number.
 * Labels, comments and attachments stay on the issue id and are not touched.
 */
export async function reassignIssueProject(
  orgId: OrgId,
  issueId: IssueId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({
      projectId,
      number: issueNumber,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

