/**
 * Moves one issue into another project of the same workspace.
 *
 * Requires the same permission as editing the issue and the same permission
 * as creating an issue in the target. The target's per-project issue quota
 * applies exactly as it does on create; a refusal writes nothing. The issue
 * takes the target's next number and its old number stays retired. A move
 * onto the project the issue is already in changes nothing and publishes
 * nothing. Title, description, status, priority, assignee, estimate, due
 * date, labels, comments, attachments and links are left as they are.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (issue.projectId === project.id) return issue;

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, project.id);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  await issueRepo.retireIssueNumber(input.orgId, issue.projectId, issue.number);
  const toNumber = await issueRepo.nextIssueNumber(input.orgId, project.id);
  const moved = await issueRepo.reassignIssueProject(
    input.orgId,
    issue.id,
    project.id,
    toNumber,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: moved.id,
    fromProjectId: issue.projectId,
    toProjectId: moved.projectId,
    fromNumber: issue.number,
    toNumber: moved.number,
  });

  return moved;
}

