 * applies exactly as it does on create; a refusal writes nothing. The issue
 * takes the target's next number and its old number stays retired. A move
 * onto the project the issue is already in changes nothing and publishes
 * nothing. Title, description, status, priority, assignee, estimate, due
 * date, labels, comments, attachments and links are left as they are.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
