import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { activityActionSchema } from "@/schemas/activity";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventType } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("move");
});

afterAll(() => {
  cleanup();
});

async function secondProject(key: string, slug: string) {
  return projectService.createProject(tenant.actors.admin, {
    orgId: tenant.org.id,
    name: slug,
    slug,
    key,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

describe("moveIssueToProject", () => {
  it("accepts issue.moved as an audit-log filter", () => {
    expect(activityActionSchema.safeParse("issue.moved").success).toBe(true);
  });

  it("moves the issue, retires the old number, and publishes one event", async () => {
    const target = await secondProject("MOV", "move-target");
    const label = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "carry",
      color: "#112233",
      description: null,
    });
    const parent = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Parent stays" }),
    );
    const issue = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, {
        title: "Carry me",
        assigneeId: tenant.userIds.admin,
      }),
      description: "keep this",
      status: "in_progress",
      priority: "high",
      estimate: 3,
      dueAt: "2026-12-01T00:00:00.000Z",
      parentId: parent.id,
      labelIds: [label.id],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "still here",
      parentId: null,
      mentionedUserIds: [],
    });
    await attachmentRepo.insertAttachment(
      {
        orgId: tenant.org.id,
        issueId: issue.id,
        filename: "note.txt",
        contentType: "text/plain",
        sizeBytes: 12,
      },
      tenant.userIds.member,
    );

    const seen: Record<string, number> = {};
    const offs = (
      ["issue.moved", "issue.created", "issue.updated", "issue.archived", "issue.status_changed"] as const
    ).map((type: TaskflowEventType) =>
      subscribe(type, () => {
        seen[type] = (seen[type] ?? 0) + 1;
      }),
    );
    const detachAudit = registerActivityListeners();
    const detachSearch = searchService.registerSearchListeners();

    try {
      const moved = await issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: target.id,
      });

      expect(moved.id).toBe(issue.id);
      expect(moved.projectId).toBe(target.id);
      expect(moved.number).toBe(1);
      expect(moved.title).toBe("Carry me");
      expect(moved.description).toBe("keep this");
      expect(moved.status).toBe("in_progress");
      expect(moved.priority).toBe("high");
      expect(moved.assigneeId).toBe(tenant.userIds.admin);
      expect(moved.estimate).toBe(3);
      expect(moved.dueAt).toBe("2026-12-01T00:00:00.000Z");
      expect(moved.parentId).toBe(parent.id);
      expect(moved.labelIds).toEqual([label.id]);
      expect(moved.authorId).toBe(issue.authorId);
      expect(moved.archivedAt).toBeNull();

      expect(seen["issue.moved"]).toBe(1);
      expect(seen["issue.created"] ?? 0).toBe(0);
      expect(seen["issue.updated"] ?? 0).toBe(0);
      expect(seen["issue.archived"] ?? 0).toBe(0);
      expect(seen["issue.status_changed"] ?? 0).toBe(0);

      const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
      expect(stored?.projectId).toBe(target.id);
      expect(stored?.number).toBe(1);

      const comments = await commentRepo.listComments(tenant.org.id, issue.id);
      expect(comments.map((comment) => comment.body)).toContain("still here");
      const attachments = await attachmentRepo.listAttachments(tenant.org.id, issue.id);
      expect(attachments.map((row) => row.filename)).toEqual(["note.txt"]);

      const sourceList = await issueService.listIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        limit: 100,
        cursor: null,
      });
      expect(sourceList.items.map((row) => row.id)).not.toContain(issue.id);
      const targetList = await issueService.listIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: target.id,
        limit: 100,
        cursor: null,
      });
      expect(targetList.items.map((row) => row.id)).toContain(issue.id);

      const sourceBoard = await issueService.getBoard(
        tenant.actors.member,
        tenant.org.id,
        tenant.project.id,
      );
      const targetBoard = await issueService.getBoard(
        tenant.actors.member,
        tenant.org.id,
        target.id,
      );
      expect(sourceBoard.flatMap((column) => column.issues).map((row) => row.id)).not.toContain(
        issue.id,
      );
      expect(targetBoard.flatMap((column) => column.issues).map((row) => row.id)).toContain(
        issue.id,
      );

      const nextOnSource = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
      expect(nextOnSource).toBeGreaterThan(issue.number);

      const created = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "After the move" }),
      );
      expect(created.number).not.toBe(issue.number);
      expect(created.number).toBeGreaterThan(issue.number);

      const audit = await listActivity(tenant.actors.member, {
        orgId: tenant.org.id,
        action: ["issue.moved"],
        projectId: target.id,
        limit: 25,
        cursor: null,
      });
      expect(audit.items).toHaveLength(1);
      expect(audit.items[0]).toMatchObject({
        action: "issue.moved",
        actorId: tenant.userIds.member,
        subjectKind: "issue",
        subjectId: issue.id,
        projectId: target.id,
        metadata: {
          fromProjectId: tenant.project.id,
          toProjectId: target.id,
          fromNumber: issue.number,
          toNumber: 1,
        },
      });

      await searchService.indexIssue(tenant.org.id, issue);
      const movedAgain = await issueRepo.findIssueById(tenant.org.id, issue.id);
      if (movedAgain) await searchService.indexIssue(tenant.org.id, movedAgain);

      const inTarget = await searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "Carry",
        kinds: ["issue"],
        projectId: target.id,
        limit: 25,
        cursor: null,
      });
      const inSource = await searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "Carry",
        kinds: ["issue"],
        projectId: tenant.project.id,
        limit: 25,
        cursor: null,
      });
      expect(inTarget.items.map((hit) => hit.id)).toContain(issue.id);
      expect(inSource.items.map((hit) => hit.id)).not.toContain(issue.id);
    } finally {
      for (const off of offs) off();
      detachAudit();
      detachSearch();
    }
  });

  it("is a no-op inside the same project", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Stay put" }),
    );
    const seen: unknown[] = [];
    const off = subscribe("issue.moved", (payload) => {
      seen.push(payload);
    });
    try {
      const again = await issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: tenant.project.id,
      });
      expect(again).toMatchObject({
        id: issue.id,
        projectId: issue.projectId,
        number: issue.number,
        title: issue.title,
      });
      expect(seen).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("refuses without edit or create permission and leaves the row", async () => {
    const target = await secondProject("REF", "refused");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Viewer cannot move" }),
    );
    await expect(
      issueService.moveIssueToProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: target.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.projectId).toBe(tenant.project.id);
    expect(stored?.number).toBe(issue.number);
  });

  it("refuses a move into a project that is at its issue quota", async () => {
    const quota = await createTenant("movequota", "free");
    const target = await projectService.createProject(quota.actors.admin, {
      orgId: quota.org.id,
      name: "Full",
      slug: "full",
      key: "FULL",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quota.org.id, target.id, { title: `Full ${number}` }),
        quota.actors.member.userId,
        number,
      );
    }
    const issue = await issueService.createIssue(
      quota.actors.member,
      issueInput(quota.org.id, quota.project.id, { title: "Does not fit" }),
    );
    await expect(
      issueService.moveIssueToProject(quota.actors.member, {
        orgId: quota.org.id,
        issueId: issue.id,
        toProjectId: target.id,
      }),
    ).rejects.toThrow(/allows no more issues/);
    const stored = await issueRepo.findIssueById(quota.org.id, issue.id);
    expect(stored?.projectId).toBe(quota.project.id);
    expect(stored?.number).toBe(issue.number);
  });

  it("does not reissue a number after the issue moves away and back", async () => {
    const target = await secondProject("BCK", "move-back");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Round trip" }),
    );
    const original = issue.number;
    await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: target.id,
    });
    const returned = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: tenant.project.id,
    });
    expect(returned.projectId).toBe(tenant.project.id);
    expect(returned.number).toBeGreaterThan(original);
    const follower = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Still later" }),
    );
    expect(follower.number).toBeGreaterThan(returned.number);
    expect(follower.number).not.toBe(original);
  });
});

